// PROTOTYPE (ULT-8). Installed by the Ultima setup-next registry item.
// Next.js 16 Turbopack runs Babel automatically when this file exists.
const path = require('node:path');

module.exports = {
  presets: ['next/babel'],
  plugins: [
    [
      '@stylexjs/babel-plugin',
      {
        dev: process.env.NODE_ENV !== 'production',
        runtimeInjection: false,
        enableInlinedConditionalMerge: true,
        treeshakeCompensation: true,
        aliases: { '@/*': [path.join(__dirname, '*')] },
        unstable_moduleResolution: { type: 'commonJS', rootDir: __dirname },
      },
    ],
  ],
};

// PROTOTYPE (ULT-8). Installed by the Ultima setup-next registry item.
// Extracts the StyleX CSS into the file that carries the `@stylex;` marker.
const babelConfig = require('./babel.config.js');

module.exports = {
  plugins: {
    '@stylexjs/postcss-plugin': {
      include: [
        'app/**/*.{js,jsx,ts,tsx}',
        'components/**/*.{js,jsx,ts,tsx}',
        'lib/**/*.{js,jsx,ts,tsx}',
      ],
      useCSSLayers: true,
      babelConfig: {
        babelrc: false,
        parserOpts: { plugins: ['typescript', 'jsx'] },
        plugins: babelConfig.plugins,
      },
    },
  },
};

/* PROTOTYPE (ULT-8). Installed by the Ultima setup-next registry item.
   Import this from app/layout.tsx. The PostCSS plugin replaces the marker
   below with every StyleX rule it finds. Keep it once, in one file. */
@stylex;
